import numpy as np

def fit_power_law(x, y, target):
    """Return {'a', 'b', 'r2', 'x_target'} as floats."""
    slope, intercept = np.polyfit(x, y, 1)      # fits the wrong space
    a, b = intercept, -slope
    return {'a': float(a), 'b': float(b), 'r2': 1.0, 'x_target': float((a / target) ** (1 / b))}
